package com.app.service;
import com.app.dto.SocietyOperationsReportDtos.*; import com.app.entity.*; import com.app.exception.ResourceNotFoundException; import com.app.repository.*; import com.itextpdf.kernel.pdf.*; import com.itextpdf.layout.Document; import com.itextpdf.layout.element.Cell; import com.itextpdf.layout.element.Paragraph; import com.itextpdf.layout.element.Table; import com.itextpdf.layout.properties.UnitValue; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.io.ByteArrayOutputStream; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;
@Service @RequiredArgsConstructor public class SocietyOperationsReportService {
 private final AccountRepository accounts;private final SocietyAgencyRepository agencies;private final SocietyAttendanceRepository attendance;private final SocietyDailyReportRepository dailyReports;private final SocietyDailyChecklistEntryRepository checklistEntries;private final SocietyIncidentRepository incidents;private final SocietyInspectionRepository inspections;private final SocietyShiftHandoverRepository handovers;
 @Transactional(readOnly=true) public AgencyComplianceReport agencyCompliance(Long aid,int year,int month){society(aid);YearMonth ym=YearMonth.of(year,month);LocalDate from=ym.atDay(1),to=ym.atEndOfMonth();List<SocietyAttendance> rows=attendance.findByAccountIdAndAttendanceDateBetweenOrderByAttendanceDateAsc(aid,from,to);List<AgencyComplianceRow> result=agencies.findByAccountIdAndActiveTrueOrderByNameAsc(aid).stream().map(a->{List<SocietyAttendance> own=rows.stream().filter(x->x.getRosterAssignment().getAgencyWorker()!=null&&x.getRosterAssignment().getAgencyWorker().getAgency().getId().equals(a.getId())).toList();long expected=(long)a.getRequiredHeadcount()*ym.lengthOfMonth(),present=own.stream().filter(x->Set.of("PRESENT","LATE","HALF_DAY").contains(x.getStatus())).count(),replacements=own.stream().filter(x->x.getReplacementAgencyWorker()!=null).count(),absent=own.stream().filter(x->"ABSENT".equals(x.getStatus())).count(),covered=present+replacements,shortage=Math.max(0,expected-covered);double compliance=expected==0?100d:Math.round(covered*10000d/expected)/100d;return AgencyComplianceRow.builder().agencyId(a.getId()).agencyName(a.getName()).requiredPerDay(a.getRequiredHeadcount()).expectedAssignments(expected).recordedAssignments(own.size()).present(present).replacements(replacements).absent(absent).shortage(shortage).compliancePercent(compliance).build();}).toList();return AgencyComplianceReport.builder().year(year).month(month).agencies(result).build();}
 @Transactional(readOnly=true) public SupervisorPerformanceReport supervisorPerformance(Long aid,LocalDate from,LocalDate to){society(aid);if(to.isBefore(from))throw new IllegalArgumentException("End date cannot be before start date");List<SocietyDailyReport> reports=dailyReports.findByAccountIdAndReportDateBetween(aid,from,to).stream().filter(x->x.getSubmittedBy()!=null).toList();Map<Long,User> people=reports.stream().map(SocietyDailyReport::getSubmittedBy).collect(Collectors.toMap(User::getId,Function.identity(),(a,b)->a));LocalDateTime start=from.atStartOfDay(),end=to.plusDays(1).atStartOfDay();List<SocietyDailyChecklistEntry> ce=checklistEntries.findByAccountIdAndOperationDateBetween(aid,from,to);List<SocietyIncident> ir=incidents.findByAccountIdAndOccurredAtBetween(aid,start,end);List<SocietyInspection> ix=inspections.findByAccountIdAndCompletedAtBetween(aid,start,end);List<SocietyShiftHandover> hs=handovers.findByAccountIdAndShiftDateBetween(aid,from,to);List<SupervisorPerformanceRow> rows=people.values().stream().map(u->{long submitted=reports.stream().filter(x->x.getSubmittedBy().getId().equals(u.getId())).count(),acked=reports.stream().filter(x->x.getSubmittedBy().getId().equals(u.getId())&&x.getAcknowledgedAt()!=null).count();return SupervisorPerformanceRow.builder().userId(u.getId()).supervisorName(u.getName()).reportsSubmitted(submitted).reportsAcknowledged(acked).onTimeReports(reports.stream().filter(x->x.getSubmittedBy().getId().equals(u.getId())&&x.getSubmittedAt()!=null&&!x.getSubmittedAt().isAfter(x.getReportDate().plusDays(1).atStartOfDay())).count()).checklistCompletions(ce.stream().filter(x->x.getCompletedBy()!=null&&x.getCompletedBy().getId().equals(u.getId())&&Boolean.TRUE.equals(x.getCompleted())).count()).incidentsRecorded(ir.stream().filter(x->x.getCreatedBy().getId().equals(u.getId())).count()).inspectionsCompleted(ix.stream().filter(x->x.getCompletedBy()!=null&&x.getCompletedBy().getId().equals(u.getId())).count()).handoversSent(hs.stream().filter(x->x.getSender().getId().equals(u.getId())).count()).acknowledgementPercent(submitted==0?0:Math.round(acked*10000d/submitted)/100d).build();}).sorted(Comparator.comparing(SupervisorPerformanceRow::getSupervisorName,String.CASE_INSENSITIVE_ORDER)).toList();return SupervisorPerformanceReport.builder().from(from).to(to).supervisors(rows).build();}
 public ExportFile exportAgency(Long aid,int year,int month,String format){AgencyComplianceReport r=agencyCompliance(aid,year,month);String[] h={"Agency","Required/day","Expected","Recorded","Present","Replacements","Absent","Shortage","Compliance %"};List<String[]> rows=r.getAgencies().stream().map(x->new String[]{x.getAgencyName(),String.valueOf(x.getRequiredPerDay()),String.valueOf(x.getExpectedAssignments()),String.valueOf(x.getRecordedAssignments()),String.valueOf(x.getPresent()),String.valueOf(x.getReplacements()),String.valueOf(x.getAbsent()),String.valueOf(x.getShortage()),String.valueOf(x.getCompliancePercent())}).toList();return export("agency-compliance-"+year+"-"+String.format("%02d",month),"Agency compliance",h,rows,format);}
 public ExportFile exportSupervisor(Long aid,LocalDate from,LocalDate to,String format){SupervisorPerformanceReport r=supervisorPerformance(aid,from,to);String[] h={"Supervisor","Reports","Acknowledged","On time","Checklist","Incidents","Inspections","Handovers","Ack %"};List<String[]> rows=r.getSupervisors().stream().map(x->new String[]{x.getSupervisorName(),String.valueOf(x.getReportsSubmitted()),String.valueOf(x.getReportsAcknowledged()),String.valueOf(x.getOnTimeReports()),String.valueOf(x.getChecklistCompletions()),String.valueOf(x.getIncidentsRecorded()),String.valueOf(x.getInspectionsCompleted()),String.valueOf(x.getHandoversSent()),String.valueOf(x.getAcknowledgementPercent())}).toList();return export("supervisor-performance-"+from+"-"+to,"Supervisor performance",h,rows,format);}
 private ExportFile export(String name,String title,String[] headers,List<String[]> rows,String format){if("csv".equalsIgnoreCase(format)){StringBuilder b=new StringBuilder();b.append(String.join(",",headers)).append('\n');rows.forEach(row->{b.append(Arrays.stream(row).map(this::csv).collect(Collectors.joining(","))).append('\n');});return new ExportFile(name+".csv","text/csv",b.toString().getBytes(StandardCharsets.UTF_8));}if(!"pdf".equalsIgnoreCase(format))throw new IllegalArgumentException("Format must be csv or pdf");ByteArrayOutputStream out=new ByteArrayOutputStream();try(Document d=new Document(new PdfDocument(new PdfWriter(out)))){d.add(new Paragraph(title).setBold().setFontSize(16));Table t=new Table(UnitValue.createPercentArray(headers.length)).useAllAvailableWidth();for(String h:headers)t.addHeaderCell(new Cell().add(new Paragraph(h).setBold()));for(String[] row:rows)for(String v:row)t.addCell(new Cell().add(new Paragraph(v==null?"":v)));d.add(t);}return new ExportFile(name+".pdf","application/pdf",out.toByteArray());}
 private String csv(String v){String s=v==null?"":v;return '"'+s.replace("\"","\"\"")+'"';}private void society(Long aid){accounts.findById(aid).filter(x->x.getAccountType()==AccountType.SOCIETY&&Boolean.TRUE.equals(x.getActive())).orElseThrow(()->new ResourceNotFoundException("Society not found"));}
}
